"""Sequential diagnostic staircase and paired probe-cost comparison, disposable only."""
from pathlib import Path
import hashlib,json,os,signal,subprocess,sys,time
ROOT=Path('/tmp/tofudb-authority-group-20261001')
OUT=Path(__file__).resolve().parent
BINARY=OUT/'candidate-build/tofu-db'
BEFORE=OUT/'current-production-baseline-build/tofu-db'
manifest={'format':'tofudb.profile-experiments/v1','scope':'synthetic DolphinFS, strict durability, embedded abandon/reopen, no process-crash certification','legs':[]}

if (OUT/'capacity-projection-manifest.json').exists(): manifest=json.loads((OUT/'capacity-projection-manifest.json').read_text())

def run(name, conversations, every, perf=False, backend="tofudb", binary=None):
    # Backends share deadlines, content, arrivals and durability contract.
    command=[sys.executable,'benchmarks/conversation_concurrency.py','--binary',str(binary or BINARY),
        '--native-client','embedded','--backend',backend,'--directory',str(OUT),'--conversations',str(conversations),
        '--rounds','4','--chunk-bytes','8192','--stream-interval-ms','1000','--output',str(OUT/(name+'.json'))]
    if perf:
        command=['perf','record','-F','49','-e','cpu-clock','--call-graph','dwarf,4096',
                 '--mmap-pages','128','-o',str(OUT/(name+'.data')),'--',*command]
    env=dict(os.environ,TOFU_DB_REQUEST_PROFILE_EVERY=str(every))
    if backend == 'sqlite': env.pop('TOFU_DB_REQUEST_PROFILE_EVERY', None)
    start=time.monotonic(); print('START',name,flush=True)
    with (OUT/(name+'.log')).open('w') as log:
        process=subprocess.Popen(command,cwd=ROOT,env=env,stdout=log,stderr=subprocess.STDOUT,start_new_session=True)
        timed_out=False
        try: code=process.wait(timeout=600)
        except subprocess.TimeoutExpired:
            timed_out=True;os.killpg(process.pid,signal.SIGKILL);code=process.wait(timeout=30)
    entry={'name':name,'conversations':conversations,'backend':backend,'sample_every':every,'perf':perf,
           'command':command,'exit_code':code,'timed_out':timed_out,'wall_seconds':time.monotonic()-start}
    report_path=OUT/(name+'.json')
    if report_path.exists():
        report=json.loads(report_path.read_text())
        entry.update({k:report.get(k) for k in ['correctness_passed','error_count','passed','client_peak_rss_bytes','recovered_exact_content','binary_sha256','native_build_info','native_library_build_info']})
        entry['latency_ms']={k:report.get('latency_ms',{}).get(k) for k in ['submit_to_running','stream_scheduled','settle']}
        profile=report.get('storage_metrics',{}).get('requestProfile',{})
        entry['profile']={k:profile.get(k) for k in ['seen','selected','dropped','retainedBytes','activeRequestBytes']}
        if profile.get('enabled'):
            sys.path.insert(0, str(Path('/tmp/tofudb-profiling-20260930') if Path('/tmp/tofudb-profiling-20260930').exists() else ROOT))
            from scripts.tofudb_profile_report import analyze
            analysis=analyze(report)
            (OUT/(name+'-analysis.json')).write_text(json.dumps(analysis,indent=2)+'\n')
            entry['profile'].update(wait_percent=analysis['wait_percent'],completed=analysis['requests'])
    manifest['legs'].append(entry)
    (OUT/'capacity-projection-manifest.json').write_text(json.dumps(manifest,indent=2)+'\n')
    print('DONE',name,json.dumps(entry['profile']) if 'profile' in entry else str(code),flush=True)
    if timed_out: raise SystemExit('Availability timeout: '+name)
    if not entry.get('correctness_passed'):
        if binary == BEFORE: print('BASELINE_CORRECTNESS_FAILURE_RETAINED',name,flush=True)
        else: raise SystemExit('Candidate correctness failed: '+name)

mode=sys.argv[1] if len(sys.argv)>1 else 'smoke'
if mode=='candidate':
    run('projection-candidate-1000',1000,0)
if mode=='profiled':
    run('projection-profiled-candidate-1000',1000,1)
if mode=='smoke':
    run('anchors-128',128,1)
if mode=='paired':
    for name,binary in [('anchors-before-1',BEFORE),('anchors-after-1',BINARY),('anchors-after-2',BINARY),('anchors-before-2',BEFORE)]:
        run(name+'-1000',1000,1,binary=binary)

if mode=='paired_off':
    for name,binary in [('projection-off-before-1',BEFORE),('projection-off-after-1',BINARY),('projection-off-after-2',BINARY),('projection-off-before-2',BEFORE)]:
        run(name+'-1000',1000,0,binary=binary)

if mode=='continue_paired_off':
    for name,binary in [('projection-off-after-1',BINARY),('projection-off-after-2',BINARY),('projection-off-before-2',BEFORE)]:
        run(name+'-1000',1000,0,binary=binary)
